import json, os

with open('/root/autodl-tmp/rl-active-probe-fl/eto_repo/data/alfworld_sft.json') as f:
    expert = json.load(f)

failures = []
with open('/root/autodl-tmp/rl-active-probe-fl/data/trajectories/train_part0.jsonl') as f:
    for line in f:
        if line.strip():
            failures.append(json.loads(line))

# Expert: 'data/json_2.1.1/train/<task_type>-<obj>-<recep>-<room>/trial_T...'
# Failure: '/root/autodl-tmp/alfworld_data/json_2.1.1/train/<task_type>-<obj>-<recep>-<room>/trial_T.../game.tw-pddl'
# Use the trial directory as key

def extract_trial_key(gf):
    parts = gf.rstrip('/').split('/')
    # Find the trial_T... part
    for i, p in enumerate(parts):
        if p.startswith('trial_T'):
            # Return task_dir/trial_dir
            if i >= 1:
                return parts[i-1] + '/' + p
            return p
    return gf

expert_keys = set()
for item in expert:
    if 'game_file' in item:
        expert_keys.add(extract_trial_key(item['game_file']))

fail_keys = set()
for item in failures:
    if 'game_file' in item:
        fail_keys.add(extract_trial_key(item['game_file']))

overlap = expert_keys & fail_keys
print(f'Expert unique trials: {len(expert_keys)}')
print(f'Failure unique trials: {len(fail_keys)}')
print(f'Overlap (potential DPO pairs): {len(overlap)}')

# Show some overlap examples
if overlap:
    for k in list(overlap)[:3]:
        print(f'  Overlap: {k}')
else:
    # Try matching by task_dir only (without trial)
    expert_task_dirs = set()
    for item in expert:
        gf = item.get('game_file', '')
        parts = gf.rstrip('/').split('/')
        for i, p in enumerate(parts):
            if p.startswith('trial_T') and i >= 1:
                expert_task_dirs.add(parts[i-1])
                break

    fail_task_dirs = set()
    for item in failures:
        gf = item.get('game_file', '')
        parts = gf.rstrip('/').split('/')
        for i, p in enumerate(parts):
            if p.startswith('trial_T') and i >= 1:
                fail_task_dirs.add(parts[i-1])
                break

    task_overlap = expert_task_dirs & fail_task_dirs
    print(f'Expert unique task dirs: {len(expert_task_dirs)}')
    print(f'Failure unique task dirs: {len(fail_task_dirs)}')
    print(f'Task-level overlap: {len(task_overlap)}')
    if task_overlap:
        for k in list(task_overlap)[:5]:
            print(f'  Task overlap: {k}')

# Also check total failure count
print(f'Total failure trajectories: {len(failures)}')
"
